"""Unit tests for the bindings corpus driver: manifest checks, layout parsing and comparison."""

import json
import tempfile
import unittest
from pathlib import Path

from corpus import bindings_corpus as bc

GENERATED = """\
// Generated by Bindings_Generator.
P :: struct {
 a: u8 #align 4;
 b: u32;
 bits: u8;
}
Q :: struct #no_padding {
 x: u16;
}

#scope_file
#assert(size_of(P) == 12);
#assert(align_of(P) == 4);
#assert(offset_of(P, "a") == 0);
#assert(offset_of(P, "b") == 4);
#assert(offset_of(P, "bits") == 8);
#assert(size_of(Q) == 2);
#assert(align_of(Q) == 2);
#assert(offset_of(Q, "x") == 0);
"""

CLANG = """\
*** Dumping AST Record Layout
         0 | struct P
         0 |   uint8_t a
         4 |   uint32_t b
         8 |   uint8_t bits
           | [sizeof=12, align=4]

*** Dumping AST Record Layout
         0 | struct (unnamed at /lib/q.h:3:9)
         0 |   uint16_t x
           | [sizeof=2, align=2]

*** Dumping AST Record Layout
         0 | struct Outer
         0 |   struct Inner
         0 |     int deep
         4 |   int tail[2]
         0 |   unsigned int flags:3
           | [sizeof=12, align=4]
"""


def manifest(libraries, triples=None):
    return {
        "triples": triples or {"x86_64-linux-gnu": {"os": "linux"}},
        "libraries": libraries,
    }


def library(**overrides):
    lib = {
        "id": "demo",
        "url": "https://example.invalid/demo.tar.gz",
        "sha256": "0" * 64,
        "root": "demo-1",
        "headers": ["demo.h"],
        "include": ["."],
        "triples": {},
    }
    lib.update(overrides)
    return lib


class ManifestTest(unittest.TestCase):
    def check(self, document):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "libraries.json"
            path.write_text(json.dumps(document))
            return bc.load_manifest(path)

    def test_the_repository_manifest_is_valid(self):
        manifest = bc.load_manifest()
        self.assertEqual(len(manifest["libraries"]), 9)
        for lib in manifest["libraries"]:
            self.assertRegex(lib["sha256"], r"^[0-9a-f]{64}$", lib["id"])

    def test_a_skip_needs_a_reason(self):
        lib = library(triples={"x86_64-linux-gnu": {"skip": " "}})
        with self.assertRaisesRegex(bc.ManifestError, "skipped without a reason"):
            self.check(manifest([lib]))

    def test_a_bad_digest_is_rejected(self):
        with self.assertRaisesRegex(bc.ManifestError, "sha256"):
            self.check(manifest([library(sha256="abc")]))

    def test_a_triple_must_be_declared(self):
        lib = library(triples={"avr": {"skip": "no port"}})
        with self.assertRaisesRegex(bc.ManifestError, "avr is not a manifest triple"):
            self.check(manifest([lib]))

    def test_duplicate_ids_are_rejected(self):
        with self.assertRaisesRegex(bc.ManifestError, "duplicate id"):
            self.check(manifest([library(), library()]))

    def test_a_skipped_cell_may_not_also_override_its_includes(self):
        lib = library(triples={"x86_64-linux-gnu": {"skip": "no port", "include": ["x"]}})
        with self.assertRaisesRegex(bc.ManifestError, "also overrides"):
            self.check(manifest([lib]))


class PlanTest(unittest.TestCase):
    def test_the_triple_override_adds_its_include_and_flags(self):
        lib = library(include=["inc"], clang=["-DX=1"], triples={"avr": {"include": ["port"], "clang": ["-mmcu=atmega328p"]}})
        plan = bc.cell_plan(lib, "avr")
        self.assertEqual(plan["include"], ["inc", "port"])
        self.assertEqual(plan["clang"], ["-DX=1", "-mmcu=atmega328p"])

    def test_a_skipped_triple_has_no_plan_but_its_reason(self):
        lib = library(triples={"avr": {"skip": "needs 32-bit ints"}})
        self.assertEqual(bc.cell_plan(lib, "avr"), {"skip": "needs 32-bit ints"})


class ParserTest(unittest.TestCase):
    def test_the_generator_asserts_become_records(self):
        layouts = bc.generated_layouts(GENERATED)
        self.assertEqual(layouts["P"], {"fields": {"a": 0, "b": 4, "bits": 8}, "size": 12, "align": 4})
        self.assertEqual(layouts["Q"]["size"], 2)

    def test_clang_records_keep_direct_members_and_skip_nested_and_bitfields(self):
        layouts = bc.clang_layouts(CLANG)
        self.assertEqual(layouts["P"], {"fields": {"a": 0, "b": 4, "bits": 8}, "size": 12, "align": 4})
        self.assertEqual(layouts["Outer"]["fields"], {"tail": 4})
        self.assertNotIn("Inner", layouts)
        self.assertNotIn("deep", layouts["Outer"]["fields"])
        self.assertNotIn("flags", layouts["Outer"]["fields"])

    def test_an_unnamed_clang_record_is_kept_under_an_anonymous_key(self):
        layouts = bc.clang_layouts(CLANG)
        anonymous = [name for name in layouts if bc.is_anonymous(name)]
        self.assertEqual(len(anonymous), 1)
        self.assertEqual(layouts[anonymous[0]]["fields"], {"x": 0})


class CompareTest(unittest.TestCase):
    def test_matching_layouts_count_records_and_fields(self):
        result = bc.compare(bc.generated_layouts(GENERATED), bc.clang_layouts(CLANG))
        self.assertEqual(result.mismatches, [])
        self.assertEqual(result.records, 2)
        self.assertEqual(result.fields, 3 + 1)

    def test_a_wrong_offset_is_a_mismatch(self):
        generated = {"P": {"size": 12, "align": 4, "fields": {"b": 8}}}
        result = bc.compare(generated, bc.clang_layouts(CLANG))
        self.assertEqual(result.mismatches, ["P.b: offset generator 8 clang 4"])

    def test_a_wrong_size_and_alignment_are_mismatches(self):
        generated = {"P": {"size": 8, "align": 2, "fields": {}}}
        result = bc.compare(generated, bc.clang_layouts(CLANG))
        self.assertEqual(result.mismatches, ["P: size generator 8 clang 12", "P: align generator 2 clang 4"])

    def test_a_typedef_of_an_unnamed_record_matches_by_its_fields(self):
        generated = {"Renamed": {"size": 2, "align": 2, "fields": {"x": 0}}}
        result = bc.compare(generated, bc.clang_layouts(CLANG))
        self.assertEqual(result.unmatched, [])
        self.assertEqual(result.records, 1)

    def test_an_ambiguous_anonymous_match_is_unmatched_not_passed(self):
        text = CLANG + """
*** Dumping AST Record Layout
         0 | struct (unnamed at /lib/other.h:1:1)
         0 |   uint16_t x
           | [sizeof=2, align=2]
"""
        generated = {"Renamed": {"size": 2, "align": 2, "fields": {"x": 0}}}
        result = bc.compare(generated, bc.clang_layouts(text))
        self.assertEqual(result.unmatched, ["Renamed"])
        self.assertEqual(result.records, 0)

    def test_a_record_clang_never_dumped_is_unmatched(self):
        result = bc.compare({"Missing": {"size": 1, "align": 1, "fields": {}}}, {})
        self.assertEqual(result.unmatched, ["Missing"])


class FormatTest(unittest.TestCase):
    def test_a_failed_header_names_the_header_in_the_report(self):
        result = {"library": "demo", "triple": "avr"}
        bc.failed(result, "error", "demo.h: boom", "x")
        self.assertIn("ERROR demo.h: boom", bc.format_line(result))

    def test_the_first_error_skips_warnings_that_mention_no_error(self):
        text = "Bindings_Generator: omitted max_align_t: unsupported\nBindings_Generator: demo.h:1:1: error: bad\nlast"
        self.assertEqual(bc.first_error(text), "demo.h:1:1: error: bad")

    def test_a_clean_cell_reports_its_counts(self):
        line = bc.format_line({"library": "demo", "triple": "avr", "status": "ok", "records": 2, "fields": 4, "unmatched": []})
        self.assertIn("2 records, 4 fields", line)
        self.assertNotIn("unmatched", line)


class SandboxTest(unittest.TestCase):
    def test_a_cell_with_no_headers_to_check_is_not_silently_ok(self):
        lib = library(triples={"avr": {"skip": "not here"}})
        result = bc.run_cell({"triples": {"avr": {"os": "none"}}, "libc": "x", "config": "y", "libraries": []}, lib, "avr", Path("/nonexistent"), "clang", False)
        self.assertEqual(result["status"], "skipped")


if __name__ == "__main__":
    unittest.main()
